import json
import hashlib
import hmac
import os
import re
from urllib.parse import parse_qs
from http.server import HTTPServer, BaseHTTPRequestHandler

# Configuration
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
DB_COLLECTIONS = {}


class SecureQueryBuilder:
    """Builds safe database queries with input sanitization."""

    DANGEROUS_OPERATORS = [
        '$where', '$regex', '$expr', '$function',
        '$accumulator', '$addFields', '$lookup'
    ]

    ALLOWED_COMPARISON_OPS = [
        '$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin'
    ]

    def __init__(self, collection_name):
        self.collection = collection_name
        self.filters = {}
        self._audit_log = []

    def sanitize_operator(self, op):
        """Block dangerous MongoDB operators."""
        if op in self.DANGEROUS_OPERATORS:
            raise ValueError(f"Operator {op} is not permitted")
        return op

    def sanitize_value(self, value):
        """Ensure values are safe for query inclusion."""
        if isinstance(value, str):
            # Block any string that looks like a JSON operator
            if value.startswith('$'):
                raise ValueError(f"String values cannot start with $")
            return value
        elif isinstance(value, (int, float, bool)):
            return value
        elif isinstance(value, list):
            return [self.sanitize_value(v) for v in value]
        elif isinstance(value, dict):
            # Allow comparison operator dicts but validate them
            sanitized = {}
            for k, v in value.items():
                if k.startswith('$'):
                    self.sanitize_operator(k)
                    if k not in self.ALLOWED_COMPARISON_OPS:
                        raise ValueError(f"Operator {k} not in allowed list")
                sanitized[k] = v  # Operator values are trusted after op validation
            return sanitized
        elif value is None:
            return None
        else:
            raise ValueError(f"Unsupported value type: {type(value)}")

    def add_filter(self, field, value):
        """Add a filter condition to the query."""
        # Validate field name
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_.]*$', field):
            raise ValueError(f"Invalid field name: {field}")
        if field.startswith('$'):
            raise ValueError("Field names cannot start with $")

        sanitized = self.sanitize_value(value)
        self.filters[field] = sanitized
        self._audit_log.append(('filter', field, repr(sanitized)))
        return self

    def build(self):
        """Build the final query document."""
        return dict(self.filters)


def parse_typed_value(raw_value):
    """Parse a query parameter value, preserving types.

    Supports JSON-encoded values for complex queries:
      ?age={"$gte": 18}  -> {'$gte': 18}
      ?name=alice        -> 'alice'
      ?score=42          -> 42
    """
    if not raw_value:
        return ''

    # Try JSON parse for structured values
    if raw_value.startswith('{') or raw_value.startswith('['):
        try:
            parsed = json.loads(raw_value)
            return parsed
        except json.JSONDecodeError:
            pass

    # Try numeric
    try:
        if '.' in raw_value:
            return float(raw_value)
        return int(raw_value)
    except ValueError:
        pass

    return raw_value


def authenticate_request(headers):
    """Verify request authentication token."""
    auth_header = headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return None

    token = auth_header[7:]
    parts = token.split('.')
    if len(parts) != 3:
        return None

    payload_b64, timestamp, signature = parts

    # Verify signature
    expected = hmac.new(
        SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
        f"{payload_b64}.{timestamp}".encode(),
        hashlib.sha256
    ).hexdigest()

    if not hmac.compare_digest(signature, expected):
        return None

    try:
        payload = json.loads(
            __import__('base64').b64decode(payload_b64 + '==').decode()
        )
        return payload
    except Exception:
        return None


class QueryHandler(BaseHTTPRequestHandler):

    def do_GET(self):
        """Handle search queries."""
        if '?' not in self.path:
            self.send_error(400, "Missing query parameters")
            return

        path, query_string = self.path.split('?', 1)

        # Extract collection from path
        path_parts = path.strip('/').split('/')
        if len(path_parts) < 2 or path_parts[0] != 'api':
            self.send_error(404, "Not found")
            return

        collection = path_parts[1]
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', collection):
            self.send_error(400, "Invalid collection name")
            return

        # Parse query parameters
        params = parse_qs(query_string, keep_blank_values=True)

        # Build query
        builder = SecureQueryBuilder(collection)

        try:
            for field, values in params.items():
                if field.startswith('_'):
                    continue  # Skip meta-parameters

                raw_value = values[0] if len(values) == 1 else values

                if isinstance(raw_value, list):
                    # Multiple values for same param -> $in query
                    typed_values = [parse_typed_value(v) for v in raw_value]
                    builder.add_filter(field, {'$in': typed_values})
                else:
                    typed_value = parse_typed_value(raw_value)
                    builder.add_filter(field, typed_value)

            query = builder.build()

            # Execute query (simulated)
            results = self._execute_query(collection, query)

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({
                'results': results,
                'query': query,
                'count': len(results)
            }).encode())

        except ValueError as e:
            self.send_error(400, str(e))

    def _execute_query(self, collection, query):
        """Simulate MongoDB-style query execution."""
        data = DB_COLLECTIONS.get(collection, [])
        results = []

        for doc in data:
            if self._matches(doc, query):
                results.append(doc)

        return results

    def _matches(self, doc, query):
        """Check if document matches query filters."""
        for field, condition in query.items():
            doc_value = self._get_nested(doc, field)

            if isinstance(condition, dict):
                for op, op_value in condition.items():
                    if op == '$eq' and doc_value != op_value:
                        return False
                    elif op == '$ne' and doc_value == op_value:
                        return False
                    elif op == '$gt' and not (doc_value is not None and doc_value > op_value):
                        return False
                    elif op == '$gte' and not (doc_value is not None and doc_value >= op_value):
                        return False
                    elif op == '$lt' and not (doc_value is not None and doc_value < op_value):
                        return False
                    elif op == '$lte' and not (doc_value is not None and doc_value <= op_value):
                        return False
                    elif op == '$in' and doc_value not in op_value:
                        return False
                    elif op == '$nin' and doc_value in op_value:
                        return False
                    elif op == '$regex':
                        if not re.search(op_value, str(doc_value)):
                            return False
            else:
                if doc_value != condition:
                    return False

        return True

    def _get_nested(self, doc, field):
        """Get nested field value using dot notation."""
        parts = field.split('.')
        current = doc
        for part in parts:
            if isinstance(current, dict):
                current = current.get(part)
            else:
                return None
        return current


